// KSDD CRM 360 — beginner staff screens + Owner Control Centre. Loaded after app.js; uses its helpers (api, esc, fmt, toast, modal).
(function(){
'use strict';
const S={home:null,admin:null,sheet:null,lang:'both'};
const rs=p=>fmt(p);
const key=()=>Array.from(crypto.getRandomValues(new Uint8Array(12)),b=>b.toString(16).padStart(2,'0')).join('');
const L=(en,hi)=>`<span class="en">${en}</span>${hi?`<span class="hi">${hi}</span>`:''}`;
const staffRoles=['cashier','chef','storekeeper','counter','purchase','housekeeping','employee'];
const can=p=>(S.home?.perms||me?.perms||[]).includes('*')||(S.home?.perms||me?.perms||[]).includes(p);
const opt=(list,sel)=>list.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(sel)?'selected':''}>${esc(t)}</option>`).join('');
const itemName=i=>esc(i.name)+(i.name_hi?` · ${esc(i.name_hi)}`:'');
const q3=n=>Number(n).toLocaleString('en-IN',{maximumFractionDigits:3});

/* ---------------- Staff app ---------------- */
const TILES={
 cashier:[['cash-in','↙','Cash IN','नकद आया','green'],['cash-out','↗','Cash OUT (guided)','नकद दिया','red'],['count','#','Count Cash','कैश गिनो','blue'],['close','✓','Close Shift / Day','दिन बंद करो','dark']],
 chef:[['k-usage','◔','Daily Usage','आज का इस्तेमाल','green'],['k-request','✎','Tomorrow\'s Requirement','कल की ज़रूरत','blue'],['k-received','✓','Goods Received','सामान मिला','dark'],['problem','!','Report Problem','समस्या बताओ','red']],
 storekeeper:[['goods-in','↓','Supplier Bill + Stock IN','बिल + माल आया','green'],['goods-out','↑','Goods OUT','माल दिया','blue'],['my-receipts','▤','My Receipts','मेरी रसीदें','dark'],['stock-count','#','Stock Count','स्टॉक गिनती','red']],
 counter:[['expense','₹','Add Expense','खर्च जोड़ो','green'],['upload-bill','⌁','Upload Bill','बिल फोटो','blue'],['my-entries','≡','My Entries','मेरी एंट्री','dark'],['pending','…','Pending Review','जाँच बाकी','red']],
 purchase:[['p-list','≡','Pending Purchase List','खरीद लिस्ट','green'],['p-order','+','Create Order','ऑर्डर बनाओ','blue'],['p-track','⇢','Track Delivery','डिलीवरी','dark'],['p-mine','▤','My Orders','मेरे ऑर्डर','red']],
 housekeeping:[['checklist','✓','Today\'s Checklist','आज की लिस्ट','green'],['checklist','✓','Mark Completed','पूरा किया','blue'],['problem','!','Report Problem','समस्या बताओ','red']],
 employee:[['self','₹','My Salary','मेरी सैलरी','green'],['advance','↗','Request Advance','एडवांस माँगो','blue'],['problem','!','Report Problem','समस्या बताओ','red']],
};
async function loadHome(){ S.home=await api('/api/crm-home'); }
function staffShell(){
  const h=S.home,u=h.user,tiles=TILES[u.role]||TILES.employee;
  app.innerHTML=`<div class="crm-staff lang-${S.lang}"><header class="crm-top"><div><b>${esc(u.name)}</b><small>${esc(u.label)} · ${esc(h.businessDate)}</small></div><div class="crm-top-actions"><button data-crm="lang" class="crm-chip">${S.lang==='both'?'EN':'हि/EN'}</button><button data-crm="logout" class="crm-chip">↪</button></div></header>
  <main class="crm-main">${u.role==='cashier'?cashierStrip():''}<div class="crm-tiles">${tiles.map(t=>`<button class="crm-tile ${t[4]}" data-crm="${t[0]}"><span class="i">${t[1]}</span>${L(t[2],t[3])}</button>`).join('')}</div>${staffBelow()}</main>
  <nav class="crm-bottom"><button data-crm="home">${L('Home','होम')}</button><button data-crm="tasks">${L('My Tasks','काम')}</button><button data-crm="my-entries">${L('My Entries','एंट्री')}</button><button data-crm="profile">${L('Profile','प्रोफ़ाइल')}</button></nav></div>`;
}
function cashierStrip(){ const c=S.home.cash; const st=c.day.workflow;
  return `<section class="crm-cashbar"><div><small>${L('Expected cash in drawer','दराज़ में होना चाहिए')}</small><b>${rs(c.expected)}</b></div><div><small>Opening</small>${c.day.openingSet?rs(c.day.opening):'<em>Not set</em>'}</div><div><small>IN</small>${rs(c.cashIn)}</div><div><small>OUT</small>${rs(c.cashOut)}</div><div><small>Status</small>${badge(st,st==='draft'?'':'blue')}</div></section>`; }
function listCard(title,rows,empty){ return `<section class="crm-card"><h3>${title}</h3>${rows.length?rows.join(''):`<p class="crm-empty">${empty}</p>`}</section>`; }
function staffBelow(){ const h=S.home,r=h.user.role; let out='';
  if(r==='cashier'){ const c=h.cash;
    if(c.handoversToAck.length) out+=listCard(L('Handover to accept','हैंडओवर स्वीकारें'),c.handoversToAck.map(x=>`<div class="crm-row"><span>${esc(x.outgoing)} → you · ${rs(x.counted)}${x.variance?` (diff ${rs(x.variance)})`:''}</span><button data-crm="ack-handover" data-id="${x.id}" class="primary">Accept</button></div>`),'');
    out+=listCard(L('Approved payments to give','मंज़ूर भुगतान'),c.vouchers.map(v=>`<div class="crm-row"><span><b>${esc(v.payee)}</b><small>${esc(v.voucher_no)} · ${esc(v.kind)} · ${esc(v.category||'')}</small></span><button class="primary" data-crm="pay-voucher" data-id="${v.id}">Pay ${rs(v.amount)}</button></div>`),'No approved payments waiting.');
    out+=`<div class="crm-actions-row"><button data-crm="driver">🚕 ${L('Bus / Taxi tip','ड्राइवर टिप')}</button><button data-crm="handover">⇄ ${L('Shift handover','शिफ्ट बदलो')}</button><button data-crm="problem">! ${L('Problem','समस्या')}</button></div>`;
    out+=listCard(L('Today\'s cash entries','आज की एंट्री'),c.today.slice().reverse().slice(0,25).map(e=>`<div class="crm-row"><span>${esc(e.time)} · ${esc(e.name)}<small>${esc(e.receipt||'')} ${esc(e.category||'')}</small></span><b class="${['sale','payment-in'].includes(e.type)?'pos':'neg'}">${['sale','payment-in'].includes(e.type)?'+':'−'}${rs(e.amount)}</b></div>`),'No cash entries yet.');
  }
  if(r==='chef'){ out+=`<div class="crm-actions-row"><button data-crm="k-previous">↺ ${L('My previous list','पिछली लिस्ट')}</button></div>`; out+=listCard(L('My lists','मेरी लिस्ट'),(h.kitchen?.requests||[]).map(k=>`<div class="crm-row"><span><b>${esc(k.target_date)}</b> · ${esc(k.location)}<small>${k.lines.length} items</small></span>${badge(k.status,k.status==='submitted'?'':'blue')}</div>`),'No lists yet.'); }
  if(r==='storekeeper'){ const s=h.store;
    out+=listCard(L('Kitchen lists to verify','रसोई लिस्ट जाँचें'),s.toVerify.map(k=>`<div class="crm-row"><span><b>${esc(k.location)}</b> for ${esc(k.target_date)}<small>${k.lines.length} items</small></span><button class="primary" data-crm="verify" data-id="${k.id}">Verify & issue</button></div>`),'Nothing to verify.');
    out+=listCard(L('Pending deliveries','आने वाला माल'),s.pos.map(p=>`<div class="crm-row"><span><b>${esc(p.po_no)}</b> · ${esc(p.supplier)}<small>${esc(p.expected_date||'')}</small></span>${badge(p.status)}</div>`),'No open orders.');
    out+=listCard(L('Low stock','कम स्टॉक'),s.low.map(i=>`<div class="crm-row"><span>${itemName(i)}</span><b class="neg">${q3(i.quantity)} ${esc(i.unit)}</b></div>`),'All items above reorder level.');
    out+=`<div class="crm-actions-row"><button data-crm="k-usage">◔ ${L('Kitchen daily usage','रसोई इस्तेमाल')}</button><button data-crm="wastage">✕ ${L('Wastage / expired','खराब माल')}</button><button data-crm="problem">! ${L('Problem','समस्या')}</button></div>`; }
  if(r==='counter') out+=listCard(L('My requests','मेरी रिक्वेस्ट'),(h.myRequests||[]).map(v=>`<div class="crm-row"><span><b>${esc(v.payee)}</b><small>${esc(v.voucher_no)} · ${esc(v.category||'')}</small></span><span>${rs(v.amount)} ${badge(v.status,v.status==='paid'?'blue':'')}</span></div>`),'No requests yet.');
  if(r==='purchase'){ out+=listCard(L('To buy','खरीदना है'),h.purchase.needed.map(n=>`<div class="crm-row"><span>${esc(n.name)}${n.name_hi?' · '+esc(n.name_hi):''}<small>${esc(n.location)} for ${esc(n.target_date)}</small></span><b>${q3(n.qty)} ${esc(n.unit)}</b></div>`),'Nothing pending.'); }
  if(r==='housekeeping') out+=(h.checklists||[]).map(c=>listCard(L('Checklist','चेकलिस्ट'),c.items.map(i=>`<label class="crm-check"><input type="checkbox" data-check="${esc(c.template)}" value="${esc(i)}" ${c.done.includes(i)?'checked':''}> ${esc(i)}</label>`),'')).join('');
  if(r==='employee') out+=selfCard();
  return out;
}
function selfCard(){ const s=S.home.self; if(!s) return listCard('My salary',[],'Your login is not linked to an employee record yet. Ask the owner.');
  return listCard(L('My salary','मेरी सैलरी'),s.payroll.map(p=>`<div class="crm-row"><span><b>${esc(p.month)}</b><small>Gross ${rs(p.gross)} · Advance ${rs(p.advance)}</small></span><span>${rs(p.net)} ${badge(p.approved?'approved':'draft')}</span></div>`),'No payroll yet.')
   +listCard(L('Advances taken','लिया गया एडवांस'),s.advances.map(a=>`<div class="crm-row"><span>${esc(a.date)} <small>recover in ${esc(a.payroll_month)}</small></span><b>${rs(a.amount)}</b></div>`),'No advances.')
   +listCard(L('My requests','मेरी रिक्वेस्ट'),s.requests.map(a=>`<div class="crm-row"><span>${esc(a.voucher_no)} · ${esc(a.date)}</span><span>${rs(a.amount)} ${badge(a.status)}</span></div>`),'—'); }

/* ---- Sheets (full-screen simple forms) ---- */
function sheet(title,hi,body,form,submit='Save / सेव करो'){
  modal.classList.add('crm-sheet'); $('#modal-body').innerHTML=`<form data-crm-form="${form}" class="crm-form"><div class="crm-sheet-head"><h2>${L(title,hi)}</h2><button type="button" data-crm="close-sheet" aria-label="Close">×</button></div><input type="hidden" name="client_key" value="${key()}">${body}<div class="form-error" id="crm-error"></div><button class="primary crm-submit">${submit}</button></form>`; modal.showModal(); setTimeout(()=>modal.querySelector('input[autofocus],select[autofocus]')?.focus(),50); }
const money=(name='amount',label='Amount ₹ / रकम')=>`<label class="crm-field">${label}<input name="${name}" type="number" inputmode="decimal" step="0.01" min="0.01" required autofocus class="crm-big"></label><div class="crm-quick">${[50,100,200,500,1000,2000].map(n=>`<button type="button" data-add="${n}" data-for="${name}">+${n}</button>`).join('')}</div>`;
const fld=(label,name,type='text',extra='')=>`<label class="crm-field">${label}<input name="${name}" type="${type}" ${extra}></label>`;
const sel=(label,name,opts,extra='')=>`<label class="crm-field">${label}<select name="${name}" ${extra}>${opts}</select></label>`;
const photo=(req=false)=>`<label class="crm-field crm-photo">📷 ${L('Bill photo','बिल फोटो')}${req?' *':''}<input type="file" accept="image/*,application/pdf" capture="environment" data-photo ${req?'required':''}><input type="hidden" name="proof_file_id"><small data-photo-status></small></label>`;
const itemOpts=()=>opt((S.home.items||[]).map(i=>[i.id,i.name+(i.name_hi?' · '+i.name_hi:'')+' ('+i.unit+')']));
const locOpts=(kind,sel)=>opt((S.home.locations||[]).filter(l=>!kind||l.kind===kind).map(l=>[l.id,l.name+(l.name_hi?' · '+l.name_hi:'')]),sel);
const lineRows=(cols,n=1)=>`<div class="crm-lines" data-cols='${JSON.stringify(cols)}'>${Array.from({length:n},()=>lineRow(cols)).join('')}</div><button type="button" class="crm-add-line" data-crm="add-line">+ ${L('Add item','आइटम जोड़ो')}</button>`;
function lineRow(cols,vals={}){ return `<div class="crm-line"><input list="crm-items" class="crm-item-search" placeholder="Search item / आइटम खोजो" value="${esc(vals.label||'')}" data-item-id="${esc(vals.item_id||'')}">${cols.map(c=>`<input type="number" inputmode="decimal" step="0.001" min="0" placeholder="${esc(c[1])}" data-col="${c[0]}" value="${esc(vals[c[0]]??'')}" ${c[2]||''}>`).join('')}<button type="button" data-crm="del-line" aria-label="Remove">×</button></div>`; }
function itemsDatalist(){ return `<datalist id="crm-items">${(S.home.items||[]).map(i=>`<option value="${esc(i.name)}${i.name_hi?' · '+esc(i.name_hi):''}" data-id="${i.id}">`).join('')}</datalist>`; }
function readLines(form,required=[]){ const items=S.home.items||[]; return [...form.querySelectorAll('.crm-line')].map(r=>{ const s=r.querySelector('.crm-item-search').value.trim(); if(!s) return null; const it=items.find(i=>s===i.name+(i.name_hi?' · '+i.name_hi:'')||s.toLowerCase()===i.name.toLowerCase()||s===i.name_hi||(i.aliases||'').toLowerCase().split(',').map(x=>x.trim()).includes(s.toLowerCase()));
  if(!it) throw Error('Unknown item: '+s+'. Pick from the list.'); const o={item_id:it.id}; r.querySelectorAll('[data-col]').forEach(i=>o[i.dataset.col]=i.value); required.forEach(k=>{if(o[k]===''||o[k]===undefined)throw Error('Enter quantity for '+it.name);}); return o; }).filter(Boolean); }

const SHEETS={
 'cash-in':()=>sheet('Cash IN','नकद आया',`${money()}${sel('From where / कहाँ से','category',opt(Object.entries(S.home.cash.inCategories)),'required')}${fld('Given by (name) / किसने दिया','from')}${fld('Note / नोट','note')}<p class="crm-hint">Petpooja sales come automatically. Use this only for cash that is <b>not</b> a POS sale (home cash, owner money, credit collection).</p>`,'cash-in'),
 'cash-out':()=>sheet('Cash OUT','नकद दिया',`${money()}${sel('For what / किस लिए','category',opt(Object.entries(S.home.cash.outCategories).map(([k,v])=>[k,k+' · '+v])),'required')}${fld('Paid to / किसे दिया','paid_to','text','required')}${photo()}${fld('Note','note')}<p class="crm-hint">Above ${rs(S.home.cash.directLimit)} the manager must approve a voucher first.</p>`,'cash-out'),
 count:(kind='spot')=>sheet(kind==='closing'?'Final cash count':'Count Cash',kind==='closing'?'आख़िरी गिनती':'कैश गिनो',`<input type="hidden" name="kind" value="${kind}"><div class="crm-denoms">${S.home.cash.denoms.map(d=>`<label>₹${d/100}<input type="number" inputmode="numeric" min="0" step="1" name="d${d}" data-denom="${d}" placeholder="0"></label>`).join('')}<label>Coins ₹<input type="number" inputmode="decimal" min="0" step="0.01" name="coins" data-denom="coins" placeholder="0"></label></div><div class="crm-total">Total <b id="crm-count-total">₹0</b><small>Expected ${rs(S.home.cash.expected)}</small></div>`,'count','Save count / गिनती सेव'),
 close:()=>{ const c=S.home.cash; if(c.day.workflow!=='draft') return toast('Day already '+c.day.workflow+'. Manager will review.'); if(!c.lastCount||c.lastCount.kind!=='closing') return SHEETS.count('closing');
   const diff=c.lastCount.total-c.expected; sheet('Close Day','दिन बंद',`<div class="crm-total">Counted <b>${rs(c.lastCount.total)}</b><small>Expected ${rs(c.expected)} · Difference <b class="${diff?'neg':''}">${rs(diff)}</b></small></div>${diff?fld('Why is cash different? / फर्क क्यों है? *','note','text','required'):''}<p class="crm-hint">After submit, the manager reviews and closes. The owner gets the report by email.</p><button type="button" class="crm-link" data-crm="recount">Count again</button>`,'close','Submit for closing / जमा करो'); },
 handover:()=>sheet('Shift handover','शिफ्ट हैंडओवर',`${sel('Incoming cashier / अगला कैशियर','incoming_user_id',opt(S.home.cash.staff.map(s=>[s.id,s.name])),'required')}<div class="crm-denoms">${S.home.cash.denoms.map(d=>`<label>₹${d/100}<input type="number" min="0" step="1" name="d${d}" data-denom="${d}" placeholder="0"></label>`).join('')}<label>Coins ₹<input type="number" min="0" step="0.01" name="coins" data-denom="coins"></label></div><div class="crm-total">Total <b id="crm-count-total">₹0</b><small>Expected ${rs(S.home.cash.expected)}</small></div>${fld('Note (if different)','note')}`,'handover','Hand over / सौंपो'),
 driver:()=>sheet('Bus / Taxi tip','ड्राइवर टिप',`${sel('Type','kind',opt([['taxi','Taxi (fixed '+rs(S.home.cash.taxiIncentive)+')'],['bus','Bus driver']]))}${fld('Driver name','driver_name','text','required')}${fld('Mobile','phone','tel','inputmode="numeric" maxlength="10"')}${fld('Vehicle number','vehicle_no','text','required style="text-transform:uppercase"')}<label class="crm-check"><input type="checkbox" name="yellow_plate" value="1"> Yellow plate (commercial)</label>${fld('Amount ₹ (bus only)','amount','number','step="0.01" min="0"')}${fld('Trip / bus ref','trip_ref')}${fld('Passengers','passengers','number','min="0"')}<label class="crm-check"><input type="checkbox" name="free_food" value="1"> Free food given</label><input type="hidden" name="pay_now" value="1">`,'driver','Save & pay'),
 problem:()=>sheet('Report Problem','समस्या बताओ',`${fld('What is the problem? / क्या दिक्कत है','title','text','required autofocus')}${sel('Type','category',opt([['maintenance','Repair / मरम्मत'],['food-safety','Food safety / खाना सुरक्षा'],['housekeeping','Cleaning / सफ़ाई'],['customer','Customer complaint / शिकायत'],['other','Other']]))}${fld('Details','detail')}<label class="crm-check"><input type="checkbox" name="urgent" value="1"> Urgent / ज़रूरी</label>${photo()}`,'problem','Send / भेजो'),
 'k-request':(prefill)=>{ const rows=prefill||[]; sheet("Tomorrow's Requirement",'कल की ज़रूरत',`${fld('For date','target_date','date','value="'+S.home.tomorrow+'" required')}${sel('Kitchen','location_id',locOpts('kitchen'))}${itemsDatalist()}<div class="crm-line-head"><span>Item</span><span>Total needed</span><span>Have now</span></div>${rows.length?`<div class="crm-lines" data-cols='[["required","Need"],["available","Have"]]'>${rows.map(r=>lineRow([['required','Need'],['available','Have']],r)).join('')}</div><button type="button" class="crm-add-line" data-crm="add-line">+ Add item</button>`:lineRows([['required','Need'],['available','Have']],4)}${fld('Note / urgent items','note')}<p class="crm-hint">"Total needed" is everything required for the day. "Have now" is what is already in the kitchen. The store issues the difference; only what the store lacks is bought.</p>`,'k-request','Submit list / लिस्ट भेजो'); },
 'k-previous':async()=>{ const r=await api('/api/crm-kitchen-last?before='+encodeURIComponent(S.home.tomorrow)); if(!r.request) return toast('No previous list found.');
   const items=S.home.items; SHEETS['k-request'](r.items.map(x=>{const it=items.find(i=>i.id===x.item_id)||{name:'?'};return {item_id:x.item_id,label:it.name+(it.name_hi?' · '+it.name_hi:''),required:Number(x.required_qty),available:''};})); toast('Loaded list for '+r.request.target_date+'. Edit and submit.'); },
 'k-received':()=>{ const req=(S.home.kitchen?.requests||[]).find(k=>['issued','partial'].includes(k.status)&&!k.acknowledged_by); if(!req) return toast('Nothing issued to you yet.');
   sheet('Goods Received','सामान मिला',`<input type="hidden" name="request_id" value="${req.id}">${req.lines.map(l=>`<label class="crm-field">${esc(l.name)} ${l.name_hi?'· '+esc(l.name_hi):''} <small>issued ${q3(l.issued_qty)} ${esc(l.unit)}</small><input type="number" step="0.001" min="0" name="r${l.id}" value="${Number(l.issued_qty)}"></label>`).join('')}`,'k-received','Confirm / पुष्टि'); },
 'goods-in':()=>sheet('Goods IN','माल आया',`${sel('Supplier / सप्लायर','supplier_id',opt(S.home.store.suppliers.map(s=>[s.id,s.name])),'required')}${sel('Against order (optional)','po_id','<option value="">—</option>'+opt(S.home.store.pos.map(p=>[p.id,p.po_no+' · '+p.supplier])))}${sel('Store location','location_id',locOpts('store'))}${itemsDatalist()}<div class="crm-line-head"><span>Item</span><span>Qty</span><span>Rate ₹</span></div>${lineRows([['qty','Qty'],['rate','Rate']],3)}${fld('Bill number (credit bill)','bill_reference')}${fld('Bill amount ₹','bill_amount','number','step="0.01" min="0"')}${photo()}<p class="crm-hint">Receiving goods does <b>not</b> pay the supplier. A bill number creates a payable for accounts.</p>`,'goods-in'),
 'goods-out':()=>sheet('Goods OUT','माल दिया',`${sel('From','from_location_id',locOpts('store'))}${sel('To department / किसे','to_location_id',locOpts('kitchen'),'required')}${fld('Received by','received_by','text','required')}${itemsDatalist()}<div class="crm-line-head"><span>Item</span><span>Qty</span></div>${lineRows([['qty','Qty']],3)}`,'goods-out'),
 'add-bill':()=>sheet('Add Bill','बिल जोड़ो',`${sel('Supplier','supplier_id',opt(S.home.store.suppliers.map(s=>[s.id,s.name])),'required')}${fld('Bill number','reference','text','required')}${money()}${fld('Bill date','date','date','value="'+S.home.businessDate+'"')}${photo(true)}`,'add-bill'),
 'stock-count':()=>sheet('Stock Count','स्टॉक गिनती',`${sel('Location','location_id',locOpts())}${itemsDatalist()}<div class="crm-line-head"><span>Item</span><span>Counted</span></div>${lineRows([['counted','Counted']],5)}<p class="crm-hint">Differences go to the manager for approval before stock changes. Write the reason in Note per item if different.</p>${fld('Reason for differences','reason')}`,'stock-count'),
 wastage:()=>sheet('Wastage / Expired','खराब माल',`${sel('Type','kind',opt([['wastage','Wastage'],['expired','Expired'],['damaged','Damaged'],['return','Return to supplier']]))}${sel('Location','location_id',locOpts())}${sel('Item','item_id',itemOpts())}${fld('Quantity','qty','number','step="0.001" min="0.001" required')}${fld('Reason','reason','text','required')}`,'wastage'),
 verify:(id)=>{ const k=S.home.store.toVerify.find(x=>x.id===Number(id)); const bal=(item)=>Number((S.home.store.balances.find(b=>b.item_id===item&&S.home.locations.find(l=>l.id===b.location_id)?.name==='Main Store')||{}).quantity||0);
   sheet('Verify kitchen list','रसोई लिस्ट जाँच',`<input type="hidden" name="request_id" value="${k.id}"><p>${esc(k.location)} · ${esc(k.target_date)}</p>${k.lines.map(l=>{const sh=Number(l.shortage_qty),st=bal(l.item_id),iss=Math.min(sh,st);return `<label class="crm-field">${esc(l.name)} ${l.name_hi?'· '+esc(l.name_hi):''}<small>need ${q3(l.required_qty)} · kitchen has ${q3(l.kitchen_available)} · short ${q3(sh)} · store ${q3(st)} ${esc(l.unit)}</small><input type="number" step="0.001" min="0" max="${Math.min(sh,st)}" name="i${l.id}" value="${iss}"></label>`;}).join('')}<p class="crm-hint">Whatever the store cannot issue goes to the purchase list automatically.</p>`,'verify','Issue & confirm'); },
 expense:(needPhoto=false)=>sheet(needPhoto?'Upload Bill':'Add Expense',needPhoto?'बिल फोटो':'खर्च जोड़ो',`<input type="hidden" name="kind" value="expense">${money()}${sel('Category','category',opt(Object.entries(S.home.outCategories||{}).map(([k,v])=>[k,k+' · '+v])))}${fld('Paid to / shop','payee','text','required')}${photo(needPhoto)}${fld('Note','note')}<p class="crm-hint">Goes to the manager for approval. The cashier pays/records it after approval.</p>`,'expense','Send for approval'),
 'upload-bill':()=>SHEETS.expense(true),
 'p-order':()=>{ const n=S.home.purchase.needed; sheet('Create Order','ऑर्डर बनाओ',`${sel('Supplier','supplier_id',opt(S.home.purchase.suppliers.map(s=>[s.id,s.name])),'required')}${fld('Expected delivery','expected_date','date')}${itemsDatalist()}<div class="crm-line-head"><span>Item</span><span>Qty</span><span>Rate ₹</span></div><div class="crm-lines" data-cols='[["qty","Qty"],["rate","Rate"]]'>${(n.length?n:[{}]).map(x=>lineRow([['qty','Qty'],['rate','Rate']],x.item_id?{item_id:x.item_id,label:x.name+(x.name_hi?' · '+x.name_hi:''),qty:Number(x.qty)}:{})).join('')}</div><button type="button" class="crm-add-line" data-crm="add-line">+ Add item</button><input type="hidden" name="request_item_ids" value="${n.map(x=>x.id).join(',')}">`,'p-order','Create order'); },
 advance:()=>sheet('Request Advance','एडवांस माँगो',`<input type="hidden" name="kind" value="advance">${money()}${fld('Reason','note','text','required')}`,'advance','Send request'),
};
function staffListView(kind){ const h=S.home; let title,rows;
  if(kind==='my-entries'){ title=L('My entries','मेरी एंट्री'); rows=h.mine.map(e=>`<div class="crm-row"><span>${esc(e.date)} · ${esc(e.name)}<small>${esc(e.receipt_no||'')} ${e.voided?'(voided)':''}</small></span><b>${rs(e.amount)}</b></div>`).concat((h.myRequests||[]).map(v=>`<div class="crm-row"><span>${esc(v.voucher_no)} · ${esc(v.payee)}</span><span>${rs(v.amount)} ${badge(v.status)}</span></div>`)); }
  else if(kind==='pending'){ title=L('Pending review','जाँच बाकी'); rows=(h.myRequests||[]).filter(v=>v.status==='requested').map(v=>`<div class="crm-row"><span>${esc(v.voucher_no)} · ${esc(v.payee)}</span><span>${rs(v.amount)}</span></div>`); }
  else if(kind==='p-list'||kind==='tasks'&&h.purchase){ title=L('Pending purchase list','खरीद लिस्ट'); rows=h.purchase.needed.map(n=>`<div class="crm-row"><span>${esc(n.name)}<small>${esc(n.location)} · ${esc(n.target_date)}</small></span><b>${q3(n.qty)} ${esc(n.unit)}</b></div>`); }
  else if(kind==='p-track'||kind==='p-mine'){ title=L('Orders','ऑर्डर'); rows=h.purchase.orders.map(p=>`<div class="crm-row"><span>${esc(p.po_no)} · ${esc(p.supplier)}<small>${esc(p.expected_date||'')}</small></span>${badge(p.status)}</div>`); }
  else if(kind==='self'){ app.querySelector('.crm-main').innerHTML=selfCard(); return; }
  else if(kind==='profile'){ title=L('Profile','प्रोफ़ाइल'); rows=[`<div class="crm-row"><span>${esc(h.user.name)}<small>${esc(h.user.label)}</small></span><button data-crm="password">Change password</button></div>`]; }
  else { title=L('My tasks','मेरे काम'); rows=[`<p class="crm-empty">Use the buttons on Home.</p>`]; }
  app.querySelector('.crm-main').innerHTML=`<button class="crm-link" data-crm="home">← Home</button>`+listCard(title,rows,'Nothing here yet.'); }

async function upload(input){ const f=input.files[0]; if(!f)return; const st=input.closest('label').querySelector('[data-photo-status]'); st.textContent='Uploading…';
  let blob=f; if(f.type.startsWith('image/')){ const img=await createImageBitmap(f); const sc=Math.min(1,1400/Math.max(img.width,img.height)); const c=document.createElement('canvas'); c.width=Math.round(img.width*sc); c.height=Math.round(img.height*sc); c.getContext('2d').drawImage(img,0,0,c.width,c.height); blob=await new Promise(r=>c.toBlob(r,'image/jpeg',0.72)); }
  const data=await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(String(fr.result).split(',')[1]);fr.readAsDataURL(blob);});
  try{ const r=await api('/api/crm-upload',{name:f.name,data}); input.closest('label').querySelector('[name="proof_file_id"]').value=r.file_id; st.textContent='✓ Photo saved'; }catch(e){ st.textContent=e.message; input.value=''; } }
function denoms(form){ const o={}; form.querySelectorAll('[data-denom]').forEach(i=>{ if(i.value!=='')o[i.dataset.denom]=i.value; }); return o; }
function countTotal(form){ let t=0; form.querySelectorAll('[data-denom]').forEach(i=>{ const v=Number(i.value||0); t+=i.dataset.denom==='coins'?Math.round(v*100):v*Number(i.dataset.denom); }); const el=form.querySelector('#crm-count-total'); if(el) el.textContent=rs(t); }

async function submitStaff(kind,form){ const b=Object.fromEntries(new FormData(form)); let r,msg='Saved ✓';
  const post=async(route,body)=>{ try{ return await api('/api/'+route,body); }catch(e){ if(/same amount and category|same amount and date/.test(e.message)&&confirm(e.message+'\n\nOK = yes, it is a new entry')) return api('/api/'+route,{...body,confirm_duplicate:1}); throw e; } };
  switch(kind){
   case 'cash-in': r=await post('crm-cash-in',b); msg=`Receipt ${r.receipt_no} · ${rs(Math.round(b.amount*100))} IN`; break;
   case 'cash-out': r=await post('crm-cash-out',b); msg=`${r.receipt_no} · ${rs(Math.round(b.amount*100))} OUT`; break;
   case 'count': r=await api('/api/crm-count',{kind:b.kind,denoms:denoms(form)}); msg=`Counted ${rs(r.total)} · difference ${rs(r.difference)}`; if(b.kind==='closing'){ await loadHome(); modal.close(); staffShell(); return SHEETS.close(); } break;
   case 'close': r=await api('/api/crm-day-submit',{note:b.note||''}); msg='Day submitted ✓ Manager will close it.'; break;
   case 'handover': r=await api('/api/crm-handover',{incoming_user_id:b.incoming_user_id,denoms:denoms(form),note:b.note}); msg='Handover saved. Incoming cashier must accept.'; break;
   case 'driver': r=await api('/api/crm-driver-visit',b); msg=r.paid?'Paid ✓ '+r.voucher.voucher_no:'Sent for approval '+r.voucher.voucher_no; break;
   case 'problem': await api('/api/crm-problem',b); msg='Sent to manager ✓'; break;
   case 'k-request': await api('/api/crm-kitchen-request',{target_date:b.target_date,location_id:b.location_id,note:b.note,items:readLines(form,['required'])}); msg='List sent to store ✓'; break;
   case 'k-received': { const rec={}; Object.entries(b).forEach(([k,v])=>{if(/^r\d+$/.test(k))rec[k.slice(1)]=v;}); await api('/api/crm-kitchen-ack',{request_id:b.request_id,received:rec}); msg='Confirmed ✓'; break; }
   case 'goods-in': r=await post('crm-goods-in',{...b,lines:readLines(form,['qty'])}); msg='Goods IN saved'+(r.bill_id?' · bill recorded':''); break;
   case 'goods-out': await api('/api/crm-goods-out',{...b,lines:readLines(form,['qty'])}); msg='Goods OUT saved'; break;
   case 'add-bill': await post('crm-bill',b); msg='Bill saved for accounts'; break;
   case 'stock-count': r=await api('/api/crm-stock-count',{location_id:b.location_id,lines:readLines(form,['counted']).map(l=>({...l,reason:b.reason}))}); msg=`${r.matched} matched · ${r.review} sent for review`; break;
   case 'wastage': await api('/api/crm-wastage',b); break;
   case 'verify': { const issue={}; Object.entries(b).forEach(([k,v])=>{if(/^i\d+$/.test(k))issue[k.slice(1)]=v;}); r=await api('/api/crm-kitchen-verify',{request_id:b.request_id,issue}); msg=r.toBuy?`Issued. ${r.toBuy} item(s) sent to purchase list.`:'Issued fully ✓'; break; }
   case 'expense': r=await post('crm-voucher',{...b,kind:'expense'}); msg='Sent for approval · '+r.voucher_no; break;
   case 'p-order': r=await api('/api/crm-po',{supplier_id:b.supplier_id,expected_date:b.expected_date,lines:readLines(form,['qty']),request_item_ids:(b.request_item_ids||'').split(',').filter(Boolean)}); msg='Order '+r.po_no+' created'; break;
   case 'advance': r=await api('/api/crm-voucher',{...b,employee_id:me.user.employee_id||S.home.user.employee_id}); msg='Advance request sent'; break;
   default: if(CRM.submitters[kind]) return CRM.submitters[kind](form,b);
  }
  modal.close(); toast(msg); await loadHome(); staffShell(); }

/* ---------------- Owner / Manager Control Centre (inside the existing app) ---------------- */
function adminScreen(){ const a=data.crm; if(!a) return card('Control Centre','Loading…','');
  if(a.error) return `<div class="notification">${esc(a.error)}</div>`;
  const o=a.overview, v=o.variance; const tile=(t,val,sub='',cls='')=>`<div class="crm-stat ${cls}"><small>${t}</small><b>${val}</b>${sub?`<span>${sub}</span>`:''}</div>`;
  const sales=Object.entries(o.byAccount||{}).map(([k,x])=>`${esc(k)} ${rs(x)}`).join(' · ')||'—';
  const dayActions=o.status==='closed'?`${btn('View report','crm-open-report','',`data-date="${a.date}"`)} ${btn('PDF','crm-open-pdf','',`data-date="${a.date}"`)} ${btn('Image','crm-open-png','',`data-date="${a.date}"`)}`:(['submitted','reviewed'].includes(o.workflow)?`${btn('Approve & close day','crm-close-day','primary',`data-date="${a.date}"`)} ${btn('Send back','crm-return-day','',`data-date="${a.date}"`)}`:`<small>Waiting for the cashier to count and submit.</small> ${me.user.role==='owner'?btn('Owner close (manual count)','crm-owner-close','',`data-date="${a.date}"`):''}`);
  return `<div class="crm-stats">${tile('Total sales',rs(o.sales),sales,'featured')}${tile('Opening cash',rs(o.opening),o.openingSource==='carry'?'carried from verified close':'manual')}${tile('Cash IN',rs(o.cashIn),'receipts (non-sale) '+rs(o.receipts))}${tile('Cash OUT',rs(o.cashOut),'operating expenses '+rs(o.operatingExpenses))}${tile('Expected cash',rs(o.expected))}${tile('Counted cash',o.counted===null?'—':rs(o.counted),v?(v<0?'Shortage ':'Excess ')+rs(Math.abs(v)):'',v?'warn':'')}${tile('Vendor dues',rs(o.vendorDue),'overdue '+rs(o.vendorOverdue),o.vendorOverdue?'warn':'')}${tile('Pending approvals',String(o.pendingVouchers),'kitchen lists '+o.kitchenPending+' · to buy '+o.purchaseNeeded+' · low stock '+o.lowStock)}</div>
  <div class="section-grid">${card('Daybook closing · '+esc(a.date),'Draft → Submitted → Closed. Status: <b>'+esc(o.workflow)+'</b>',dayActions+(o.openVariances.length?`<h4>Unresolved cash differences</h4>`+table(['Date','Difference','Status','Reason'],o.openVariances.map(x=>`<tr><td>${esc(x.date)}</td><td>${rs(x.variance)}</td><td>${badge(x.variance_status)}</td><td>${esc(x.note||'')}</td></tr>`)):''))}
  ${card('Operations inbox','Everything waiting for you, in one place.',inboxTable(a.inbox))}
  ${card('Petpooja sales sync','Last import: '+(a.pos.last?esc(a.pos.last.business_date)+' · '+esc(a.pos.last.status)+' · '+esc(a.pos.last.imported_at)+' UTC':'never')+' · Windows PC sync '+(a.syncConfigured?'configured':'<b>not configured</b>'),`<form data-crm-form="pos-import"><label class="field">Petpooja day-wise payment summary CSV<input type="file" accept=".csv,text/csv" id="crm-pos-file" required></label><label class="crm-check"><input type="checkbox" name="replace" value="1"> Replace changed days (owner; open days only)</label><button class="primary">Preview import</button></form><div id="crm-pos-preview"></div>`+table(['Date','Cash','UPI','Card','Status'],a.pos.recent.map(p=>`<tr><td>${esc(p.business_date)} r${p.revision}</td><td>${rs(p.cash)}</td><td>${rs(p.upi)}</td><td>${rs(p.card)}</td><td>${badge(p.status,p.status==='reconciled'?'blue':'')}<small>${esc(p.reconcile_note||'')}</small></td></tr>`),'No imports yet'))}
  ${card('Payment vouchers','Requests → approval → cashier pays once.',table(['No','Type','Payee','Amount','Status',''],a.vouchers.slice(0,25).map(x=>`<tr><td>${esc(x.voucher_no)}</td><td>${esc(x.kind)}</td><td>${esc(x.payee)}<small> by ${esc(x.requested_name)}</small></td><td>${rs(x.amount)}</td><td>${badge(x.status)}</td><td>${x.status==='requested'?btn('Approve','crm-v-approve','',`data-id="${x.id}"`)+btn('Reject','crm-v-reject','',`data-id="${x.id}"`):''}</td></tr>`))+`<div class="crm-actions-row">${btn('+ Advance request','crm-new-advance')}${btn('+ Supplier payment','crm-new-suppay')}${btn('+ Other payment','crm-new-other')}</div>`)}
  
  ${card('Kitchen & purchase','Chef lists and what still needs buying.',table(['Date','Kitchen','Chef','Items','Status'],a.kitchen.map(k=>`<tr><td>${esc(k.target_date)}</td><td>${esc(k.location)}</td><td>${esc(k.chef)}</td><td>${k.line_count}</td><td>${badge(k.status)}</td></tr>`))+`<h4>To buy</h4>`+table(['Item','Qty','For'],a.purchaseNeeded.map(n=>`<tr><td>${esc(n.name)}</td><td>${q3(n.qty)} ${esc(n.unit)}</td><td>${esc(n.target_date)}</td></tr>`),'Nothing pending'))}
  ${card('Driver incentives','Bus / taxi visits with duplicate protection.',table(['Date','Type','Driver','Vehicle','Amount','Voucher'],a.drivers.map(d=>`<tr><td>${esc(d.visit_date)}</td><td>${esc(d.kind)}</td><td>${esc(d.driver_name)}</td><td>${esc(d.vehicle_no)}</td><td>${rs(d.amount)}</td><td>${badge(d.voucher_status||'—')}</td></tr>`)))}
  ${card('Closing reports archive','Every closed version is kept. Resend creates a new email record.',table(['Date','Version','Status',''],a.snapshots.map(s=>`<tr><td>${esc(s.date)}</td><td>v${s.version}</td><td>${esc(s.label)}</td><td>${btn('Open','crm-open-report','',`data-date="${s.date}" data-v="${s.version}"`)}${btn('PDF','crm-open-pdf','',`data-date="${s.date}" data-v="${s.version}"`)}${me.user.role==='owner'?btn('Resend','crm-resend','',`data-id="${s.id}"`):''}</td></tr>`),'No closed days yet'))}
  ${card('Email delivery','"accepted" = accepted by the SMTP server (not proof of inbox delivery). SMTP '+(a.smtpConfigured?'configured':'<b>not configured</b>'),table(['Report','Status','Tries','Result'],a.emails.map(e=>`<tr><td>${esc(e.idem_key)}</td><td>${badge(e.status,e.status==='accepted'?'blue':'')}</td><td>${e.attempts}</td><td><small>${esc(e.last_error||e.smtp_reply||'')}</small></td></tr>`),'No emails yet')+(me.user.role==='owner'?btn('Send queued emails now','crm-email-run'):''))}
  ${card('Automation log','Cron jobs and Windows-PC syncs.',table(['Job','Status','Done','Started (UTC)','Error'],a.jobs.map(j=>`<tr><td>${esc(j.job)}</td><td>${badge(j.status)}</td><td>${j.processed}</td><td>${esc(j.started_at)}</td><td><small>${esc(j.errors||'')}</small></td></tr>`),'No jobs have run yet. Set up the Hostinger cron job (DEPLOYMENT.md).'))}
  ${(CRM.adminCards||[]).map(f=>f(a)).join('')}
  ${me.user.role==='owner'?card('Users & roles','Each person sees only their own screen.',table(['Name','Email','Role','Active',''],a.users.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(a.roles[x.role]||x.role)}</td><td>${x.active?'Yes':'No'}</td><td>${btn('Edit','crm-user-edit','',`data-id="${x.id}"`)}</td></tr>`))+btn('+ Add user','crm-add-user'))+card('Policies & email','Limits, owner email, checklists.',policyForm(a.settings)):''}
  </div>`; }
function inboxTable(items){ if(!items.length) return '<p class="crm-empty">All clear ✓</p>';
  return `<div class="crm-inbox">${items.map(i=>`<div class="crm-inbox-item ${i.priority}"><div><b>${esc(i.title)}</b><small>${esc(i.module)} · ${esc(i.type)} · ${esc(i.business_date||i.created_at)}${i.raised_name?' · from '+esc(i.raised_name):''}${i.assigned_name?' · assigned '+esc(i.assigned_name):''}${i.status==='clarify'?' · <b>clarification asked</b>':''}</small>${i.detail?`<p>${esc(i.detail)}</p>`:''}</div><div class="crm-inbox-actions">${i.type==='goods-hold'?btn('Review','crm-sup-review','primary',`data-id="${i.ref_id}"`):''}${['voucher','stock-difference','cash-variance'].includes(i.type)?btn('Approve','crm-ib','primary',`data-id="${i.id}" data-act="approve"`)+btn('Reject','crm-ib','',`data-id="${i.id}" data-act="reject"`):(i.type==='goods-hold'?'':btn('Resolve','crm-ib','primary',`data-id="${i.id}" data-act="resolve"`))}${btn('Ask','crm-ib','',`data-id="${i.id}" data-act="clarify"`)}${btn('History','crm-ib-hist','',`data-id="${i.id}"`)}</div></div>`).join('')}</div>`; }
function policyForm(s){ const r=k=>s[k]?(Number(s[k])/100):''; const list=k=>{try{return JSON.parse(s[k]||'[]').join('\n');}catch{return '';}};
  return `<form data-crm-form="policies"><div class="form-grid">${field('Owner email(s), comma separated','owner_emails','text',s.owner_emails||'')}${field('CC','email_cc','text',s.email_cc||'')}${field('Email subject','email_subject','text',s.email_subject||'')}${field('Cashier direct Cash OUT limit ₹','cash_out_direct_limit','number',r('cash_out_direct_limit'),'step="0.01"')}${field('Bill photo required above ₹','proof_required_above','number',r('proof_required_above'),'step="0.01"')}${field('Manager approval limit ₹','manager_approval_limit','number',r('manager_approval_limit'),'step="0.01"')}${field('Taxi incentive per visit ₹','taxi_incentive','number',r('taxi_incentive'),'step="0.01"')}${field('Driver auto-approve up to ₹','driver_auto_approve_limit','number',r('driver_auto_approve_limit'),'step="0.01"')}${field('Business day ends at (hour, IST)','business_day_cutoff_hour','number',s.business_day_cutoff_hour||'4','min="0" max="8"')}</div>${['housekeeping','opening','closing'].map(t=>`<label class="field wide">${t} checklist (one per line)<textarea name="checklist_${t}" rows="4">${esc(list('checklist_'+t))}</textarea></label>`).join('')}<button class="primary">Save policies</button></form>`; }
async function loadAdmin(){ try{ data.crm=await api(`/api/crm-admin?date=${selectedDate}`); }catch(e){ data.crm={error:e.message}; } }
function crmPrompt(title,label,cb,extra=''){ showModal(title,'',`${extra}<label class="field wide">${label}<input name="note" required></label>`,'crm-prompt','Confirm'); modal.querySelector('[data-form="crm-prompt"]').dataset.crmForm='prompt'; modal.querySelector('[data-form="crm-prompt"]').removeAttribute('data-form'); S.prompt=cb; }
async function adminAction(a,t){ const id=t.dataset.id,d=t.dataset.date,v=t.dataset.v?'&v='+t.dataset.v:'';
  const done=async(m)=>{ toast(m||'Saved'); await refresh(); };
  switch(a){
   case 'crm-open-report': return window.open(`api.php?route=crm-report&date=${d}${v}`,'_blank');
   case 'crm-open-pdf': return window.open(`api.php?route=crm-report&date=${d}${v}&format=pdf`,'_blank');
   case 'crm-open-png': return window.open(`api.php?route=crm-report&date=${d}${v}&format=png`,'_blank');
   case 'crm-close-day': await api('/api/crm-day-close',{date:d}); return done('Day closed. Report saved and email queued.');
   case 'crm-return-day': return crmPrompt('Send back to cashier','Reason',async n=>{await api('/api/crm-day-return',{date:d,reason:n});done('Sent back');});
   case 'crm-owner-close': return showModal('Owner close','Use only when the cashier could not submit.',`${field('Counted cash ₹','counted','number','','required step="0.01" min="0"')}${field('Note / reason for any difference','note')}<input type="hidden" name="date" value="${d}">`,'crm-owner-close','Close day'),fixForm('owner-close');
   case 'crm-v-approve': await api('/api/crm-voucher-decide',{id,decision:'approve'}); return done('Approved — cashier can pay now');
   case 'crm-v-reject': return crmPrompt('Reject payment','Reason',async n=>{await api('/api/crm-voucher-decide',{id,decision:'reject',note:n});done('Rejected');});
   case 'crm-ib': { const act=t.dataset.act; if(act==='approve'){ const it=data.crm.inbox.find(x=>x.id==id); if(it.type==='cash-variance') return crmPrompt('Accept cash difference','Why is it accepted?',async n=>{await api('/api/crm-inbox-act',{id,act,note:n});done();}); await api('/api/crm-inbox-act',{id,act,note:'Approved'}); return done('Approved'); }
     return crmPrompt(act==='clarify'?'Ask for clarification':act==='reject'?'Reject':'Resolve','Note',async n=>{await api('/api/crm-inbox-act',{id,act,note:n});done();}); }
   case 'crm-ib-hist': { const r=await api('/api/crm-inbox-history',{id}); return showModal('History','',table(['When (UTC)','Who','Action','Note'],r.events.map(e=>`<tr><td>${esc(e.at)}</td><td>${esc(e.name||'System')}</td><td>${esc(e.action)}</td><td>${esc(e.note||'')}</td></tr>`)),'',''); }
   case 'crm-resend': await api('/api/crm-email-resend',{snapshot_id:id}); return done('Email queued');
   case 'crm-email-run': { const r=await api('/api/crm-email-run',{}); return done(`Sent ${r.sent}, failed ${r.failed}`); }
   case 'crm-user-edit': { const u=data.crm.users.find(x=>x.id==id); showModal('Edit '+esc(u.name),u.email,`<input type="hidden" name="id" value="${u.id}"><div class="form-grid">${select('Role','role',opt(Object.entries(data.crm.roles),u.role))}${select('Active','active',opt([['1','Yes'],['','No']],u.active?'1':''))}${select('Linked employee','employee_id','<option value="">—</option>'+opt(data.crm.employees.map(e=>[e.id,e.name]),u.employee_id))}${field('Cash drawer','drawer','text',u.drawer||'')}</div>`,'crm-user','Save'); return fixForm('user-update'); }
   case 'crm-add-user': return forms.user();
   case 'crm-new-advance': showModal('Salary advance request','Approval → cashier pays → recovered in payroll',`<div class="form-grid">${select('Employee','employee_id',opt(data.crm.employees.map(e=>[e.id,e.name])))}${field('Amount ₹','amount','number','','required step="0.01"')}${field('Recover in month','payroll_month','month',selectedDate.slice(0,7))}${field('Reason','note')}</div><input type="hidden" name="kind" value="advance"><input type="hidden" name="client_key" value="${key()}">`,'x','Create'); return fixForm('voucher');
   case 'crm-new-suppay': showModal('Supplier payment request','Partial payments allowed',`<div class="form-grid">${select('Bill','bill_id',opt(data.crm.bills.filter(b=>b.status!=='paid').map(b=>[b.id,b.supplier+' · '+b.reference+' · due '+fmt(b.outstanding)])))}${field('Amount ₹','amount','number','','required step="0.01"')}${field('Note','note')}</div><input type="hidden" name="kind" value="supplier"><input type="hidden" name="client_key" value="${key()}">`,'x','Create'); return fixForm('voucher');
   case 'crm-new-other': showModal('Other payment voucher','',`<div class="form-grid">${field('Payee','payee','text','','required')}${field('Amount ₹','amount','number','','required step="0.01"')}${field('Category','category')}${field('Note','note')}</div><input type="hidden" name="kind" value="other"><input type="hidden" name="client_key" value="${key()}">`,'x','Create'); return fixForm('voucher');
   default: if(CRM.adminActions[a]) return CRM.adminActions[a](t,done);
  } }
function fixForm(kind){ const f=modal.querySelector('form'); f.removeAttribute('data-form'); f.dataset.crmForm=kind; }
async function submitAdmin(kind,form){ const b=Object.fromEntries(new FormData(form));
  if(kind==='prompt'){ await S.prompt(b.note); modal.close(); return; }
  if(kind==='pos-import'){ const f=$('#crm-pos-file').files[0]; const csv=await f.text(); const p=await api('/api/crm-pos-import',{csv,preview:true});
    $('#crm-pos-preview').innerHTML=table(['Date','State','Cash','UPI','Card','Issues'],p.rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${badge(r.state)}</td><td>${rs(r.cash)}</td><td>${rs(r.upi)}</td><td>${rs(r.card)}</td><td><small>${esc(r.issues.join(' '))}</small></td></tr>`))+`<button class="primary" id="crm-pos-confirm">Confirm import</button>`;
    $('#crm-pos-confirm').onclick=async()=>{ try{ const r=await api('/api/crm-pos-import',{csv,replace:!!b.replace}); toast(`${r.imported} imported · ${r.skipped} duplicates skipped · ${r.conflicts} need review`); await refresh(); }catch(e){toast(e.message,true);} }; return; }
  if(kind==='policies'){ await api('/api/crm-settings',b); toast('Policies saved'); return refresh(); }
  if(kind==='owner-close'){ await api('/api/crm-day-close',b); modal.close(); toast('Day closed'); return refresh(); }
  if(kind==='user-update'){ await api('/api/crm-user-update',b); modal.close(); toast('User updated'); return refresh(); }
  if(kind==='voucher'){ const r=await api('/api/crm-voucher',b); modal.close(); toast('Created '+r.voucher_no); return refresh(); }
  if(CRM.adminSubmit[kind]) return CRM.adminSubmit[kind](form,b); }

/* ---------------- Wiring ---------------- */
window.CRM={ submitters:{}, adminCards:[], adminActions:{}, adminSubmit:{}, get S(){return S;}, SHEETS, sheet, L, fld, sel, photo, key, opt, listCard, loadHome:()=>loadHome(), staffShell:()=>staffShell(), staffListView:(k)=>staffListView(k),
  async takeover(m){ if(m.schema<2) return false; if(staffRoles.includes(m.user.role)){ document.body.classList.add('crm-staff-body'); await loadHome(); staffShell(); return true; } return false; } };
// Admin nav + screen + data loading (existing app keeps working; Control Centre is the first screen for owner/manager/accounts)
if(typeof nav!=='undefined'){ nav.unshift(['control','◎','Control Centre']); screens.control=adminScreen;
  // Home Cash IN fix: the old "Cash received" tile posted a SALE. It now opens the non-sales receipt form.
  if(typeof quickTiles!=='undefined') quickTiles[0]=['home-cash-in','↙','Cash IN (not a sale)','Home / owner / other receipts',''];
  const oldRefresh=refresh; refresh=async function(){ await oldRefresh(); if(me?.schema>=2&&(me.perms||[]).some(p=>p==='*'||p==='inbox')){ await loadAdmin(); if(view==='control') render(); } };
  const oldStaff=typeof staffAction==='function'?staffAction:null;
  staffAction=function(a,id,t){ if(a==='home-cash-in'){ showModal('Cash IN · not a sale','Owner money, home cash, credit collection. Creates a receipt number.',`${field('Amount ₹','amount','number','','required step="0.01" min="0.01"')}${select('From where','category',opt(Object.entries({'owner-contribution':'Owner contribution','home-cash':'Cash received from home','credit-collection':'Customer credit collection','petty-return':'Petty cash returned','bank-withdrawal':'Bank to cash withdrawal','transfer-in':'Cash transfer IN','other-receipt':'Other genuine receipt'})))}${field('Given by','from')}${field('Note','note')}<input type="hidden" name="client_key" value="${key()}">`,'x','Save receipt'); fixForm('admin-cash-in'); return true; } return oldStaff?oldStaff(a,id,t):false; };
}
const prevSubmitAdmin=submitAdmin;
document.addEventListener('click',async ev=>{ const t=ev.target.closest('[data-crm],[data-action^="crm-"],[data-add]'); if(!t) return;
  try{
   if(t.dataset.add){ const i=t.closest('form').querySelector(`[name="${t.dataset.for}"]`); i.value=(Number(i.value||0)+Number(t.dataset.add)); return; }
   if(t.dataset.action){ ev.stopPropagation(); return await adminAction(t.dataset.action,t); }
   const a=t.dataset.crm;
   if(a==='close-sheet') return modal.close();
   if(a==='logout'){ await api('/api/logout',{}); location.reload(); return; }
   if(a==='lang'){ S.lang=S.lang==='both'?'en':'both'; return staffShell(); }
   if(a==='home'){ await loadHome(); return staffShell(); }
   if(a==='add-line'){ const box=t.previousElementSibling; box.insertAdjacentHTML('beforeend',lineRow(JSON.parse(box.dataset.cols))); return; }
   if(a==='del-line'){ t.closest('.crm-line').remove(); return; }
   if(a==='recount'){ modal.close(); return SHEETS.count('closing'); }
   if(a==='ack-handover'){ await api('/api/crm-handover-ack',{id:t.dataset.id}); toast('Handover accepted'); await loadHome(); return staffShell(); }
   if(a==='pay-voucher'){ const v=S.home.cash.vouchers.find(x=>x.id==t.dataset.id); if(!confirm(`Give ${rs(v.amount)} cash to ${v.payee}?`)) return; const r=await api('/api/crm-voucher-pay',{id:v.id}); toast('Paid ✓'); await loadHome(); return staffShell(); }
   if(a==='verify') return SHEETS.verify(t.dataset.id);
   if(a==='password') return forms.password&&forms.password();
   if(['my-entries','pending','tasks','profile','p-list','p-track','p-mine','self'].includes(a)) return staffListView(a);
   if(CRM.staffActions?.[a]) return await CRM.staffActions[a](t);
   if(SHEETS[a]) return await SHEETS[a]();
  }catch(e){ toast(e.message,true); } },true);
document.addEventListener('change',async ev=>{ if(ev.target.matches('[data-photo]')) return upload(ev.target);
  if(ev.target.matches('[data-check]')){ const tpl=ev.target.dataset.check; const done=[...document.querySelectorAll(`[data-check="${tpl}"]:checked`)].map(i=>i.value); try{ const r=await api('/api/crm-checklist',{template:tpl,done}); toast(`${r.done}/${r.total} done`);}catch(e){toast(e.message,true);} } });
document.addEventListener('input',ev=>{ if(ev.target.matches('[data-denom]')) countTotal(ev.target.closest('form')); });
document.addEventListener('submit',async ev=>{ const f=ev.target.closest('[data-crm-form]'); if(!f) return; ev.preventDefault(); ev.stopImmediatePropagation(); const btnS=f.querySelector('button:not([type="button"])'); if(btnS) btnS.disabled=true;
  try{ const k=f.dataset.crmForm; if(k==='admin-cash-in'){ const b=Object.fromEntries(new FormData(f)); b.date=selectedDate; const r=await api('/api/crm-cash-in',b); modal.close(); toast('Receipt '+r.receipt_no); return refresh(); }
    if(document.body.classList.contains('crm-staff-body')&&!['prompt'].includes(k)) await submitStaff(k,f); else await prevSubmitAdmin(k,f);
  }catch(e){ const box=f.querySelector('#crm-error')||f.querySelector('#modal-error'); if(box) box.textContent=e.message; else toast(e.message,true); }
  finally{ if(btnS) btnS.disabled=false; } },true);
modal.addEventListener('close',()=>modal.classList.remove('crm-sheet'));
})();
